const paths = ["incident/report.txt","incident/optional-evidence.json","package.json","source/providers/provider-presets.json","keep.txt"];
const out = {};
for (const p of paths) {
  try {
    const r = await tools.read_file({ path: p });
    out[p] = typeof r === "string" ? r : (r.content ?? JSON.stringify(r));
  } catch (e) {
    out[p] = { error: String(e.message || e) };
  }
}
return out;

